#!/usr/bin/env bash
# Stamps a release version and commit into the moqserver binary before a release build.
# Usage: stamp-build-info.sh <version> <commit>
set -euo pipefail

if [[ $# -ne 2 || -z "$1" || -z "$2" ]]; then
  echo "usage: $0 <version> <commit>" >&2
  exit 64
fi
if [[ ! "$1" =~ ^[0-9A-Za-z.+-]+$ || ! "$2" =~ ^[0-9a-f]{7,40}$ ]]; then
  echo "version must be SemVer and commit a hex SHA" >&2
  exit 65
fi

target="$(cd "$(dirname "$0")/.." && pwd)/Sources/MoqRuntime/App/BuildStamp.swift"
cat > "${target}" <<SWIFT
// Generated by scripts/stamp-build-info.sh for a release build. Do not commit.
enum BuildStamp {
    static let version: String? = "$1"
    static let commit: String? = "$2"
}
SWIFT
echo "Stamped ${target}: $1 ($2)"
